class MarketPersistenceTest {
 MarketFixture f;
 @BeforeEach void setup(){String url=System.getenv("NIGSON_TEST_JDBC_URL");Assumptions.assumeTrue(url!=null,"market-check supplies isolated PostgreSQL");if(!url.matches("jdbc:postgresql://127.0.0.1:[0-9]+/nigson"))throw new IllegalArgumentException("LOCAL_TEST_DB_REQUIRED");var ds=new DriverManagerDataSource(url+"?currentSchema=commerce","nigson_commerce_app","mock-commerce-runtime");var jdbc=new JdbcTemplate(ds);var manager=new DataSourceTransactionManager(ds);var clock=Clock.systemUTC();var metrics=new io.micrometer.core.instrument.simple.SimpleMeterRegistry();var commands=new PlatformStore(jdbc,manager,clock,metrics);var audit=new AuditWriter(jdbc,clock,metrics);var authority=new CatalogueAuthority(jdbc);var assets=new com.nigson.commerce.files.JdbcCatalogueAssets(jdbc,"test","https://cdn.synthetic.test/assets/");var events=new ProductService(new JdbcProductRepository(jdbc,clock,assets),new JdbcTaxonomyRepository(jdbc,clock),authority,commands,audit,clock);var port=new CatalogueConfiguration().catalogueMarketChanges(jdbc,assets,events);var service=new MarketService(new JdbcMarketRepository(jdbc,clock),new MarketAuthority(jdbc,clock),port,commands,audit,clock,jdbc,manager,metrics,1000);f=new MarketFixture(jdbc,service);}
 @AfterEach void cleanup(){if(f!=null)f.close();}
 @Test void disabledCreationHasNoCommercialDefaultsAndReplaysExactly(){var first=f.create("SYNTH_"+UUID.randomUUID().toString().substring(0,8),"create");assertThat(first.enabled()).isFalse();assertThat(first.taxPolicy().isEmpty()).isTrue();assertThat(first.destinations()).isEmpty();assertThat(first.returnsPolicyRevision()).isNull();assertThat(first.retailPriceBookId()).isNull();assertThat(first.policyRevision()).isEqualTo(1);assertThat(first.version()).isZero();assertThat(f.create(first.code(),"create")).isEqualTo(first);assertThatThrownBy(()->f.create(first.code(),"different-key")).hasMessage("CONFLICT");assertThat(f.service.list()).isEmpty();assertThat(f.jdbc.queryForObject("SELECT count(*) FROM commerce.outbox_event WHERE aggregate_id=?",Integer.class,first.id())).isZero();}
 @Test void api030UpdatesDisabledDraftAtomicallyWithEventAuditAndStableReplay(){var market=f.create("SYNTH_API030","create");var input=new MarketValues.Update("Synthetic reviewed draft","NGN",false,List.of(new MarketValues.Destination("NG",EventCodec.JSON.readTree("{\"schemaVersion\":1,\"requiredFields\":[\"RECIPIENT\",\"PHONE\",\"LINE1\",\"CITY\"],\"postalPattern\":null,\"regionCodes\":[]}"),false)),EventCodec.JSON.readTree("{}"),"SYNTHETIC_DRAFT_REVISION");var after=f.service.update(f.adminActor,market.id(),0,input,"update",UUID.randomUUID());assertThat(after.enabled()).isFalse();assertThat(after.version()).isEqualTo(1);assertThat(after.policyRevision()).isEqualTo(2);assertThat(after.destinations()).extracting(MarketValues.Destination::countryCode).containsExactly("NG");assertThat(f.service.update(f.adminActor,market.id(),0,input,"update",UUID.randomUUID())).isEqualTo(after);assertThatThrownBy(()->f.service.update(f.adminActor,market.id(),0,new MarketValues.Update("Different draft","NGN",false,input.destinations(),input.taxPolicy(),input.returnsPolicyRevision()),"update",UUID.randomUUID())).hasMessage("IDEMPOTENCY_HASH_MISMATCH");assertThatThrownBy(()->f.service.update(f.adminActor,market.id(),0,input,"stale",UUID.randomUUID())).hasMessage("VERSION_MISMATCH");assertThat(f.jdbc.queryForObject("SELECT count(*) FROM commerce.audit_record WHERE resource_id=? AND action='MARKET_UPDATE'",Integer.class,market.id())).isEqualTo(1);assertThat(f.jdbc.queryForObject("SELECT count(*) FROM commerce.outbox_event WHERE aggregate_id=?",Integer.class,market.id())).isEqualTo(1);assertThat(f.service.list()).isEmpty();}
 @Test void api030AuditFailureRollsBackDraftAndEventThenSameKeyCanRetry(){var market=f.create("SYNTH_API030_AUDIT","create");var input=new MarketValues.Update("Synthetic audit rollback","NGN",false,List.of(),EventCodec.JSON.readTree("{}"),"SYNTHETIC_DRAFT");f.admin.execute("REVOKE INSERT ON commerce.audit_record FROM nigson_commerce_app");try{assertThatThrownBy(()->f.service.update(f.adminActor,market.id(),0,input,"audit-update",UUID.randomUUID())).isInstanceOf(org.springframework.dao.DataAccessException.class);assertThat(f.jdbc.queryForObject("SELECT version FROM commerce.market WHERE id=?",Long.class,market.id())).isZero();assertThat(f.jdbc.queryForObject("SELECT count(*) FROM commerce.outbox_event WHERE aggregate_id=?",Integer.class,market.id())).isZero();}finally{f.admin.execute("GRANT INSERT ON commerce.audit_record TO nigson_commerce_app");}assertThat(f.service.update(f.adminActor,market.id(),0,input,"audit-update",UUID.randomUUID()).version()).isEqualTo(1);assertThat(f.jdbc.queryForObject("SELECT count(*) FROM commerce.audit_record WHERE resource_id=? AND action='MARKET_UPDATE'",Integer.class,market.id())).isEqualTo(1);}
 @Test void api030CanAlwaysTurnOffAnEnabledMarketWithoutChangingItsDestinationRules(){var market=f.create("SYNTH_API030_SHUTDOWN","create");var rules=EventCodec.JSON.readTree("{\"schemaVersion\":1,\"requiredFields\":[],\"postalPattern\":null,\"regionCodes\":[]}");var destination=new MarketValues.Destination("NG",rules,true);f.jdbc.update("INSERT INTO commerce.market_destination(id,created_by,updated_by,market_id,country_code,address_rules,delivery_enabled) VALUES (?,'test','test',?,'NG',?::jsonb,true)",UUID.randomUUID(),market.id(),EventCodec.JSON.writeValueAsString(rules));f.jdbc.update("UPDATE commerce.market SET enabled=true WHERE id=?",market.id());var request=new MarketValues.Update(market.name(),market.currency(),false,List.of(destination),market.taxPolicy(),"SYNTHETIC_DRAFT");var disabled=f.service.update(f.adminActor,market.id(),0,request,"shutdown",UUID.randomUUID());assertThat(disabled.enabled()).isFalse();assertThat(disabled.destinations()).containsExactly(destination);assertThat(f.service.list()).isEmpty();}
 @Test void api030CompetingVersionsCommitExactlyOnePolicyEvent()throws Exception{var market=f.create("SYNTH_API030_RACE","create");var rules=EventCodec.JSON.readTree("{\"schemaVersion\":1,\"requiredFields\":[],\"postalPattern\":null,\"regionCodes\":[]}");var barrier=new CyclicBarrier(2);try(var pool=Executors.newVirtualThreadPerTaskExecutor()){var results=new ArrayList<Future<Boolean>>();for(String name:List.of("Synthetic race A","Synthetic race B")){var update=new MarketValues.Update(name,"NGN",false,List.of(new MarketValues.Destination("NG",rules,false)),EventCodec.JSON.readTree("{}"),"SYNTHETIC_DRAFT");results.add(pool.submit(()->{barrier.await();try{f.service.update(f.adminActor,market.id(),0,update,name,UUID.randomUUID());return true;}catch(com.nigson.shared.problem.Problem.Failure stale){assertThat(stale.getMessage()).isEqualTo("VERSION_MISMATCH");return false;}}));}int committed=0;for(var result:results)if(result.get(10,TimeUnit.SECONDS))committed++;assertThat(committed).isEqualTo(1);}assertThat(f.jdbc.queryForObject("SELECT version FROM commerce.market WHERE id=?",Long.class,market.id())).isEqualTo(1);assertThat(f.jdbc.queryForObject("SELECT policy_revision FROM commerce.market WHERE id=?",Long.class,market.id())).isEqualTo(2);assertThat(f.jdbc.queryForObject("SELECT count(*) FROM commerce.outbox_event WHERE aggregate_id=?",Integer.class,market.id())).isEqualTo(1);assertThat(f.jdbc.queryForObject("SELECT count(*) FROM commerce.audit_record WHERE resource_id=? AND action='MARKET_UPDATE'",Integer.class,market.id())).isEqualTo(1);}
 @Test void api030FailsClosedForActivationAndUnapprovedDeliveryAndRequiresCurrentAdmin(){var market=f.create("SYNTH_API030_DENY","create");var rules=EventCodec.JSON.readTree("{\"schemaVersion\":1,\"requiredFields\":[],\"postalPattern\":null,\"regionCodes\":[]}");var enabled=new MarketValues.Update("Synthetic market","NGN",true,List.of(),EventCodec.JSON.readTree("{}"),"SYNTHETIC_ONLY");assertThatThrownBy(()->f.service.update(f.adminActor,market.id(),0,enabled,"enable",UUID.randomUUID())).hasMessage("MARKET_RULE_VIOLATION");var delivery=new MarketValues.Update("Synthetic market","NGN",false,List.of(new MarketValues.Destination("NG",rules,true)),EventCodec.JSON.readTree("{}"),"SYNTHETIC_ONLY");assertThatThrownBy(()->f.service.update(f.adminActor,market.id(),0,delivery,"delivery",UUID.randomUUID())).hasMessage("MARKET_RULE_VIOLATION");assertThatThrownBy(()->f.service.update(f.actor,market.id(),0,enabled,"wrong-role",UUID.randomUUID())).hasMessage("ACCESS_DENIED");var orgActor=new ActorAssertion.Actor(f.administrator,f.adminActor.identityIssuer(),f.adminActor.identitySubject(),UUID.randomUUID(),Set.of("ADMIN"),Set.of(),Instant.now());assertThatThrownBy(()->f.service.update(orgActor,market.id(),0,enabled,"organization",UUID.randomUUID())).hasMessage("ACCESS_DENIED");assertThat(f.jdbc.queryForObject("SELECT version FROM commerce.market WHERE id=?",Long.class,market.id())).isZero();assertThat(f.jdbc.queryForObject("SELECT count(*) FROM commerce.outbox_event WHERE aggregate_id=?",Integer.class,market.id())).isZero();}
 @Test void missingCurrencyIsRejectedWithoutCreatingMoneyOrMarket(){assertThatThrownBy(()->f.service.create(f.actor,new MarketValues.Create("USD_SYNTH","Synthetic currency rejection","USD"),"missing",UUID.randomUUID())).hasMessage("MARKET_RULE_VIOLATION");assertThat(f.jdbc.queryForObject("SELECT count(*) FROM commerce.currency WHERE code='USD'",Integer.class)).isZero();}
 @Test void validRetailSelectionChangesPolicyButCannotActivateMarket(){var market=f.create("SYNTH_BOOK","create");UUID book=f.book("RETAIL","NGN",-60,0,true);var after=f.service.book(f.actor,market.id(),0,new MarketValues.Book(book,"Synthetic offline reviewed book"),"book",UUID.randomUUID());assertThat(after.enabled()).isFalse();assertThat(after.policyRevision()).isEqualTo(2);assertThat(after.version()).isEqualTo(1);assertThat(after.retailPriceBookId()).isEqualTo(book);assertThat(f.service.book(f.actor,market.id(),0,new MarketValues.Book(book,"Synthetic offline reviewed book"),"book",UUID.randomUUID())).isEqualTo(after);assertThatThrownBy(()->f.service.book(f.actor,market.id(),0,new MarketValues.Book(book,"Synthetic offline reviewed book"),"stale",UUID.randomUUID())).hasMessage("VERSION_MISMATCH");assertThat(EventCodec.decode(f.jdbc.queryForObject("SELECT payload::text FROM commerce.outbox_event WHERE aggregate_id=?",String.class,market.id())).path("payload").path("policy_revision").asLong()).isEqualTo(2);}
 @Test void inactiveWholesaleFutureAndExpiredBooksCannotBeAssigned(){var market=f.create("SYNTH_REJECT","create");for(UUID book:List.of(f.book("RETAIL","NGN",-60,0,false),f.book("DISTRIBUTOR","NGN",-60,0,true),f.book("RETAIL","NGN",60,0,true),f.book("RETAIL","NGN",-120,-60,true)))assertThatThrownBy(()->f.service.book(f.actor,market.id(),0,new MarketValues.Book(book,"Synthetic invalid book selection"),book.toString(),UUID.randomUUID())).hasMessage("MARKET_RULE_VIOLATION");assertThat(f.jdbc.queryForObject("SELECT version FROM commerce.market WHERE id=?",Long.class,market.id())).isZero();}
 @Test void productEligibilityUsesProductVersionAndEmitsCurrentPublicRevision(){var market=f.create("SYNTH_PRODUCT","create");var eligible=new MarketValues.Eligibility(true,"Synthetic explicit product eligibility");var after=f.service.restriction(f.content,f.product,market.id(),0,eligible,"allow",UUID.randomUUID());assertThat(after.version()).isEqualTo(1);assertThat(f.service.restriction(f.content,f.product,market.id(),0,eligible,"allow",UUID.randomUUID())).isEqualTo(after);assertThatThrownBy(()->f.service.restriction(f.content,f.product,market.id(),0,eligible,"stale",UUID.randomUUID())).hasMessage("VERSION_MISMATCH");assertThatThrownBy(()->f.service.restriction(f.content,f.product,market.id(),0,new MarketValues.Eligibility(false,eligible.reason()),"allow",UUID.randomUUID())).hasMessage("IDEMPOTENCY_HASH_MISMATCH");var denied=f.service.restriction(f.content,f.product,market.id(),1,new MarketValues.Eligibility(false,"Synthetic explicit withdrawal"),"deny",UUID.randomUUID());assertThat(denied.version()).isEqualTo(2);assertThat(f.jdbc.queryForObject("SELECT revision FROM commerce.product WHERE id=?",Long.class,f.product)).isEqualTo(3);assertThat(f.jdbc.queryForObject("SELECT eligible FROM commerce.product_market_eligibility WHERE product_id=? AND market_id=?",Boolean.class,f.product,market.id())).isFalse();assertThat(EventCodec.decode(f.jdbc.queryForObject("SELECT payload::text FROM commerce.outbox_event WHERE aggregate_id=? ORDER BY aggregate_version DESC LIMIT 1",String.class,f.product)).path("payload").path("revision").asLong()).isEqualTo(3);}
 @Test void currentRoleIdentityAndMfaAreRequiredEvenForCachedResponses(){var market=f.create("SYNTH_AUTH","create");var old=new ActorAssertion.Actor(f.finance,f.actor.identityIssuer(),f.actor.identitySubject(),null,Set.of("FINANCE"),Set.of(),Instant.now().minusSeconds(901));assertThatThrownBy(()->f.service.create(old,new MarketValues.Create(market.code(),market.name(),market.currency()),"create",UUID.randomUUID())).isInstanceOf(org.springframework.security.access.AccessDeniedException.class);f.jdbc.update("UPDATE commerce.staff_role_assignment SET revoked_at=now() WHERE party_id=?",f.finance);assertThatThrownBy(()->f.create(market.code(),"create")).hasMessage("ACCESS_DENIED");assertThatThrownBy(()->f.service.restriction(f.actor,f.product,market.id(),0,new MarketValues.Eligibility(true,"Synthetic invalid role request"),"wrong-role",UUID.randomUUID())).hasMessage("ACCESS_DENIED");}
 @Test void auditFailureRollsBackProductEligibilityRevisionEventAndAcknowledgement(){var market=f.create("SYNTH_ATOMIC","create");f.admin.execute("REVOKE INSERT ON commerce.audit_record FROM nigson_commerce_app");try{assertThatThrownBy(()->f.service.restriction(f.content,f.product,market.id(),0,new MarketValues.Eligibility(true,"Synthetic audit rollback check"),"audit",UUID.randomUUID())).isInstanceOf(org.springframework.dao.DataAccessException.class);assertThat(f.jdbc.queryForObject("SELECT version FROM commerce.product WHERE id=?",Long.class,f.product)).isZero();assertThat(f.jdbc.queryForObject("SELECT count(*) FROM commerce.product_market_eligibility WHERE product_id=?",Integer.class,f.product)).isZero();assertThat(f.jdbc.queryForObject("SELECT count(*) FROM commerce.outbox_event WHERE aggregate_id=?",Integer.class,f.product)).isZero();}finally{f.admin.execute("GRANT INSERT ON commerce.audit_record TO nigson_commerce_app");}assertThat(f.service.restriction(f.content,f.product,market.id(),0,new MarketValues.Eligibility(true,"Synthetic audit rollback check"),"audit",UUID.randomUUID()).version()).isEqualTo(1);}
 @Test void twelveSameKeysProduceOneMarketAndAudit()throws Exception{String code="SYNTH_RACE",key=UUID.randomUUID().toString();var start=new CyclicBarrier(12);try(var pool=Executors.newVirtualThreadPerTaskExecutor()){var results=new ArrayList<Future<MarketValues.Market>>();for(int i=0;i<12;i++)results.add(pool.submit(()->{start.await();for(int n=0;n<30;n++)try{return f.service.create(f.actor,new MarketValues.Create(code,"Synthetic concurrent market","NGN"),key,UUID.randomUUID());}catch(PlatformStore.Conflict busy){if(!busy.getMessage().equals("IDEMPOTENCY_IN_PROGRESS"))throw busy;Thread.sleep(40);}throw new IllegalStateException("BOUNDED_REPLAY_EXHAUSTED");}));var first=results.getFirst().get(10,TimeUnit.SECONDS);f.markets.add(first.id());for(var result:results)assertThat(result.get(10,TimeUnit.SECONDS)).isEqualTo(first);assertThat(f.jdbc.queryForObject("SELECT count(*) FROM commerce.audit_record WHERE resource_id=? AND action='MARKET_CREATE'",Integer.class,first.id())).isEqualTo(1);}}
 @Test void salePortFailsClosedUntilAllOwnedPoliciesProviderProofAndProductEligibilityAreCurrent(){var m=f.create("NG","create");var ds=f.jdbc.getDataSource();var tx=new org.springframework.transaction.support.TransactionTemplate(new DataSourceTransactionManager(ds));var port=new JdbcMarketEligibility(f.jdbc,Clock.systemUTC(),"test");var address=EventCodec.JSON.readTree("{\"countryCode\":\"NG\",\"recipient\":\"Synthetic recipient\",\"phone\":\"+2348000000000\",\"line1\":\"Synthetic offline address\",\"city\":\"Synthetic city\",\"postalCode\":\"000000\"}");var proof=new MarketEligibility.ProviderProof("NGN","NG","MOCK","SYNTHETIC_PAYMENT_ONLY","SYNTHETIC_CARRIER_ONLY",Instant.now().plusSeconds(60));assertThatThrownBy(()->port.require(m.id(),"NG",Set.of(f.product),address,proof)).hasMessage("LOCAL_TRANSACTION_REQUIRED");assertThatThrownBy(()->tx.execute(t->port.require(m.id(),"NG",Set.of(f.product),address,proof))).hasMessage("MARKET_RULE_VIOLATION");f.jdbc.update("UPDATE commerce.market SET enabled=true WHERE id=?",m.id());assertThat(f.service.list()).isEmpty();assertThatThrownBy(()->tx.execute(t->port.require(m.id(),"NG",Set.of(f.product),address,proof))).hasMessage("MARKET_RULE_VIOLATION");UUID book=f.book("RETAIL","NGN",-60,0,true);f.service.book(f.actor,m.id(),0,new MarketValues.Book(book,"Synthetic offline policy fixture"),"book",UUID.randomUUID());f.jdbc.update("UPDATE commerce.market SET tax_policy=?::jsonb,returns_policy_revision='SYNTHETIC_RETURN_ONLY' WHERE id=?","{\"schemaVersion\":1,\"mode\":\"NONE\",\"rate\":\"0\",\"rounding\":\"HALF_UP\",\"approvalReference\":\"SYNTHETIC_TAX_ONLY\"}",m.id());String rules="{\"schemaVersion\":1,\"requiredFields\":[\"RECIPIENT\",\"PHONE\",\"LINE1\",\"CITY\"],\"postalPattern\":\"^[0-9]{6}$\",\"regionCodes\":[]}";f.jdbc.update("INSERT INTO commerce.market_destination(id,created_by,updated_by,market_id,country_code,address_rules,delivery_enabled) VALUES (?,'test','test',?,'NG',?::jsonb,true)",UUID.randomUUID(),m.id(),rules);f.jdbc.update("UPDATE commerce.product SET status='ACTIVE' WHERE id=?",f.product);assertThatThrownBy(()->tx.execute(t->port.require(m.id(),"NG",Set.of(f.product),address,proof))).hasMessage("MARKET_RULE_VIOLATION");f.service.restriction(f.content,f.product,m.id(),0,new MarketValues.Eligibility(true,"Synthetic reviewed product policy"),"allow",UUID.randomUUID());assertThatThrownBy(()->tx.execute(t->port.require(m.id(),"NG",Set.of(f.product),address,null))).hasMessage("MARKET_RULE_VIOLATION");var stale=new MarketEligibility.ProviderProof("NGN","NG","MOCK","SYNTHETIC_PAYMENT_ONLY","SYNTHETIC_CARRIER_ONLY",Instant.now().minusSeconds(1));assertThatThrownBy(()->tx.execute(t->port.require(m.id(),"NG",Set.of(f.product),address,stale))).hasMessage("MARKET_RULE_VIOLATION");var sale=tx.<MarketEligibility.Sale>execute(t->port.require(m.id(),"NG",Set.of(f.product),address,proof));assertThat(sale.currency()).isEqualTo("NGN");assertThat(sale.minorUnit()).isEqualTo(2);assertThat(f.service.list()).hasSize(1);assertThat(f.service.list().getFirst().destinations()).containsExactly("NG");var prod=new JdbcMarketEligibility(f.jdbc,Clock.systemUTC(),"prod");assertThatThrownBy(()->tx.execute(t->prod.require(m.id(),"NG",Set.of(f.product),address,proof))).hasMessage("MARKET_RULE_VIOLATION");f.service.restriction(f.content,f.product,m.id(),1,new MarketValues.Eligibility(false,"Synthetic immediate product withdrawal"),"deny",UUID.randomUUID());assertThatThrownBy(()->tx.execute(t->port.require(m.id(),"NG",Set.of(f.product),address,proof))).hasMessage("MARKET_RULE_VIOLATION");}
 @Test void bookAuditFailureCannotChangePolicyOrEmitEvent(){var m=f.create("SYNTH_BOOK_AUDIT","create");UUID book=f.book("RETAIL","NGN",-60,0,true);f.admin.execute("REVOKE INSERT ON commerce.audit_record FROM nigson_commerce_app");try{assertThatThrownBy(()->f.service.book(f.actor,m.id(),0,new MarketValues.Book(book,"Synthetic atomic book selection"),"audit",UUID.randomUUID())).isInstanceOf(org.springframework.dao.DataAccessException.class);assertThat(f.jdbc.queryForObject("SELECT version FROM commerce.market WHERE id=?",Long.class,m.id())).isZero();assertThat(f.jdbc.queryForObject("SELECT count(*) FROM commerce.outbox_event WHERE aggregate_id=?",Integer.class,m.id())).isZero();}finally{f.admin.execute("GRANT INSERT ON commerce.audit_record TO nigson_commerce_app");}assertThat(f.service.book(f.actor,m.id(),0,new MarketValues.Book(book,"Synthetic atomic book selection"),"audit",UUID.randomUUID()).policyRevision()).isEqualTo(2);}
 @Test void twoCompetingBooksAtOneVersionProduceOnlyOnePolicyChange()throws Exception{var m=f.create("SYNTH_BOOK_RACE","create");UUID one=f.book("RETAIL","NGN",-60,0,true),two=f.book("RETAIL","NGN",-60,0,true);var start=new CyclicBarrier(2);try(var pool=Executors.newVirtualThreadPerTaskExecutor()){var results=new ArrayList<Future<Boolean>>();for(UUID book:List.of(one,two))results.add(pool.submit(()->{start.await();try{f.service.book(f.actor,m.id(),0,new MarketValues.Book(book,"Synthetic competing book choice"),book.toString(),UUID.randomUUID());return true;}catch(com.nigson.shared.problem.Problem.Failure stale){assertThat(stale.getMessage()).isEqualTo("VERSION_MISMATCH");return false;}}));int accepted=0;for(var r:results)if(r.get(10,TimeUnit.SECONDS))accepted++;assertThat(accepted).isEqualTo(1);}assertThat(f.jdbc.queryForObject("SELECT policy_revision FROM commerce.market WHERE id=?",Long.class,m.id())).isEqualTo(2);assertThat(f.jdbc.queryForObject("SELECT count(*) FROM commerce.outbox_event WHERE aggregate_id=?",Integer.class,m.id())).isEqualTo(1);}
 @Test void currencyMinorUnitsAndIssuerCannotBeChangedToAuthorizeCommands(){var m=f.create("SYNTH_IDENTITY","create");var wrong=new ActorAssertion.Actor(f.finance,"https://wrong.synthetic.invalid",f.actor.identitySubject(),null,Set.of("FINANCE"),Set.of(),Instant.now());assertThatThrownBy(()->f.service.create(wrong,new MarketValues.Create(m.code(),m.name(),m.currency()),"create",UUID.randomUUID())).hasMessage("ACCESS_DENIED");f.jdbc.update("UPDATE commerce.currency SET minor_unit=3 WHERE code='NGN'");try{assertThatThrownBy(()->f.create("SYNTH_WRONG_SCALE","wrong-scale")).hasMessage("MARKET_RULE_VIOLATION");}finally{f.jdbc.update("UPDATE commerce.currency SET minor_unit=2 WHERE code='NGN'");}}
 @Test void differentCurrencyBooksAndWrongNigeriaCurrencyCannotBeSelected(){var m=f.create("SYNTH_FOREIGN","create");UUID currency=UUID.randomUUID();f.jdbc.update("INSERT INTO commerce.currency(id,created_by,updated_by,code,minor_unit,active) VALUES (?,'test','test','USD',2,true)",currency);try{UUID book=f.book("RETAIL","USD",-60,0,true);assertThatThrownBy(()->f.service.book(f.actor,m.id(),0,new MarketValues.Book(book,"Synthetic currency mismatch book"),"currency",UUID.randomUUID())).hasMessage("MARKET_RULE_VIOLATION");assertThatThrownBy(()->f.service.create(f.actor,new MarketValues.Create("NG","Synthetic invalid Nigeria currency","USD"),"wrong-NG-currency",UUID.randomUUID())).hasMessage("MARKET_RULE_VIOLATION");f.jdbc.update("DELETE FROM commerce.price_book WHERE id=?",book);f.books.remove(book);}finally{f.jdbc.update("DELETE FROM commerce.currency WHERE id=?",currency);}}
}
